from __future__ import annotations
import unittest
from ttea.capability import CAPABILITY_FIXTURES, evaluate
from ttea.tournament.capability import ROUND2_CANDIDATES, capability_work_order, summarize_candidate, rank_candidates, terminal_state, CapabilityTerminalState

def good(f):
 p={"cap.protocol.basic":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"prepare\",\"action\":\"prepare_output\",\"depends_on\":[]}]}","cap.constraint.preserve_input":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"prepare\",\"action\":\"prepare_output\",\"depends_on\":[]}]}","cap.policy.guard_boundary":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"obtain_approval\",\"action\":\"request_approval\",\"depends_on\":[]}]}","cap.state.no_action":"{\"mode\":\"NO_ACTION\",\"plan\":[]}","cap.state.precondition_choice":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"commit\",\"action\":\"commit_output\",\"depends_on\":[]}]}","cap.plan.chain":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"collect\",\"action\":\"inspect_input\",\"depends_on\":[]},{\"subgoal\":\"validate\",\"action\":\"validate_item\",\"depends_on\":[\"collect\"]},{\"subgoal\":\"prepare\",\"action\":\"prepare_output\",\"depends_on\":[\"validate\"]},{\"subgoal\":\"commit\",\"action\":\"commit_output\",\"depends_on\":[\"prepare\"]}]}","cap.plan.fork_join":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"collect_input\",\"action\":\"inspect_input\",\"depends_on\":[]},{\"subgoal\":\"collect_policy\",\"action\":\"inspect_policy\",\"depends_on\":[]},{\"subgoal\":\"validate\",\"action\":\"validate_item\",\"depends_on\":[\"collect_input\",\"collect_policy\"]},{\"subgoal\":\"prepare\",\"action\":\"prepare_output\",\"depends_on\":[\"validate\"]}]}","cap.replan.failed_alternative":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"prepare\",\"action\":\"use_alternative\",\"depends_on\":[]}]}","cap.replan.state_delta":"{\"mode\":\"ACT\",\"plan\":[{\"subgoal\":\"commit\",\"action\":\"commit_output\",\"depends_on\":[]}]}"};return evaluate(f,p[f.id])
class IntegrationTests(unittest.TestCase):
 def test_order_concurrency_summary_ranking_and_terminals(self):
  order=capability_work_order("t");self.assertEqual(len(order),36);self.assertEqual([x.candidate_id for x in order[:9]],[ROUND2_CANDIDATES[0]]*9)
  results={f.id:good(f) for f in CAPABILITY_FIXTURES};a=summarize_candidate("a",results);b=summarize_candidate("b",results);self.assertEqual(a.status,"ELIGIBLE");self.assertEqual(rank_candidates((b,a))[0].candidate_id,"a")
  self.assertEqual(terminal_state((a,)),CapabilityTerminalState.COMPLETED_ELIGIBLE);self.assertEqual(terminal_state((summarize_candidate("x",results,incomplete=True),)),CapabilityTerminalState.COMPLETED_INCOMPLETE);self.assertEqual(terminal_state((summarize_candidate("x",{}),)),CapabilityTerminalState.COMPLETED_INCOMPLETE);self.assertEqual(terminal_state((a,),True),CapabilityTerminalState.BLOCKED_INTEGRITY)
